import {config,categories,seedProducts} from './data.js';
import {reconcileCatalog} from './catalog.js';
import {totals,whatsappURL,inquiryMessage,canDispatch,csvEscape,parseCSV} from './domain.js';
const $=s=>document.querySelector(s);
const paths={search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',user:'M20 21v-2a7 7 0 0 0-14 0v2 M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',bag:'M5 7h14l1 14H4L5 7Z M8 8V6a4 4 0 0 1 8 0v2',arrow:'M4 12h16 M14 6l6 6-6 6',chevron:'M9 5l7 7-7 7',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',truck:'M1 4h13v13H1V4Z M14 9h5l4 4v4h-9 M8 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0 M21 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0',snow:'M12 2v20 M3.3 7l17.4 10 M3.3 17L20.7 7 M8 4l4 4 4-4 M8 20l4-4 4 4 M3 11l5-1-1-5 M21 13l-5 1 1 5 M3 13l5 1-1 5 M21 11l-5-1 1-5',store:'M3 10v11h18V10 M2 3h20l1 7a3 3 0 0 1-5 2 3 3 0 0 1-6 0 3 3 0 0 1-6 0 3 3 0 0 1-5-2l1-7Z M9 21v-6h6v6',shield:'M12 2l9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4Z M8 12l3 3 5-6',tag:'M21 12l-9 9L2 11V2h9l10 10Z M7 7h.01',plus:'M12 5v14 M5 12h14',minus:'M5 12h14',close:'M6 6l12 12 M18 6L6 18',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',check:'M5 12l4 4L19 6',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 2',mail:'M2 4h20v16H2V4Z M2 4l10 8L22 4',phone:'M22 16.9v3a2 2 0 0 1-2.2 2 20 20 0 0 1-8.7-3.1 20 20 0 0 1-6.2-6.2A20 20 0 0 1 1.8 4 2 2 0 0 1 3.8 2h3a2 2 0 0 1 2 1.7c.1 1 .4 2 .7 2.9a2 2 0 0 1-.5 2.1L7.7 10a16 16 0 0 0 6.3 6.3l1.3-1.3a2 2 0 0 1 2.1-.5c.9.3 1.9.6 2.9.7a2 2 0 0 1 1.7 1.7',grid:'M3 3h7v7H3V3Z M14 3h7v7h-7V3Z M3 14h7v7H3v-7Z M14 14h7v7h-7v-7Z',box:'M21 7l-9-5-9 5v10l9 5 9-5V7Z M3 7l9 5 9-5 M12 12v10 M7.5 4.5l9 5',chart:'M3 3v18h18 M7 16V9 M12 16V5 M17 16v-5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 2h6l1 3 3 1 3 3v6l-3 1-1 3-3 3H9l-1-3-3-1-3-3V9l3-1 1-3 3-3Z',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',edit:'M16 3l5 5 M3 21l5-1L21 7l-5-5L3 15v6Z',info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 11v6 M12 7h.01',home:'M3 10l9-8 9 8v12h-7v-8h-4v8H3V10Z',repeat:'M3 7h15l3 3 M18 4l3 3-3 3 M21 17H6l-3-3 M6 20l-3-3 3-3',star:'M12 2l3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z',lock:'M5 10h14v12H5V10Z M8 10V6a4 4 0 0 1 8 0v4',logout:'M9 3H3v18h6 M10 12h12 M18 8l4 4-4 4'};
const icon=(name,cls='')=>`<svg aria-hidden="true" class="${cls}" viewBox="0 0 24 24"><path d="${paths[name]||paths.box}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(n);
const date=d=>new Intl.DateTimeFormat('es-AR',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Argentina/Buenos_Aires'}).format(new Date(d));
const STORE='la-montevideana-demo-v2';let storageOK=true;
function read(){try{return JSON.parse(localStorage.getItem(STORE)||'null')}catch{return null}}
const saved=read();let state=reconcileCatalog({products:structuredClone(seedProducts),settings:structuredClone(config),cart:[],favorites:[],profile:null,addresses:[],orders:[],audit:[],...saved},seedProducts,config.catalogVersion);
state.settings={...config,...state.settings,logo:config.logo,logoConfirmed:config.logoConfirmed,colors:config.colors,contact:{...config.contact,...state.settings?.contact},payment:{enabled:false,advanceRequired:true}};
let pageLimit=9,toastTimer,returnFocus=null,drawerOpen=false;
function save(){try{localStorage.setItem(STORE,JSON.stringify(state))}catch{storageOK=false;toast('No se pudo guardar. Revisá el espacio del navegador.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function audit(action){state.audit.unshift({id:crypto.randomUUID(),at:new Date().toISOString(),actor:state.profile?.name||'Operador DEMO',action});state.audit=state.audit.slice(0,250)}
function route(){const [path,query]=(location.hash.slice(1)||'/').split('?');return{path,params:new URLSearchParams(query||'')}}
function goto(url){if(location.hash==='#'+url)render();else location.hash=url}
function calc(){return totals(state.cart,state.products)}
function saleLabel(p,qty=1){return p.saleUnit==='bulto'?(qty===1?'bulto':'bultos'):(qty===1?'caja':'cajas')}
function stockLabel(p){return p.stock===null?'Stock a consultar':p.stock===0?'Sin stock informado':p.stock+' '+saleLabel(p,p.stock)+' disponibles · DEMO'}
function brand(){return `<a class="brand" href="#/" aria-label="La Montevideana, inicio">${state.settings.logoConfirmed?`<img class="official-logo" src="${esc(state.settings.logo)}" alt="Logo de La Montevideana" width="2003" height="1458"><span class="brand-type"><small>DISTRIBUCIÓN MAYORISTA</small><strong>La Montevideana</strong></span>`:`<span class="brand-type"><small>DISTRIBUCIÓN MAYORISTA</small><strong>La Montevideana</strong></span>`}</a>`}
function header(){const{path}=route();return `<div class="topbar"><div class="container"><span class="location">${icon('store')}Distribución para heladerías</span><span>Versión DEMO · Precios pendientes de carga</span></div></div><header class="header"><div class="container"><div class="header-main">${brand()}<form class="search" data-form="search" role="search"><input name="q" aria-label="Buscar productos por caja o bulto" placeholder="Buscá productos para tu heladería" value="${esc(route().params.get('q')||'')}"><button aria-label="Buscar">${icon('search')}</button></form><div class="header-tools"><a class="tool favorites-tool" href="#/cuenta?tab=favoritos" aria-label="Favoritos">${icon('heart')}</a><a class="tool" href="#/cuenta">${icon('user')}<span class="tool-text"><small>Tu comercio</small><strong>Mi cuenta</strong></span></a><button class="tool" data-action="cart" aria-label="Abrir pedido, ${calc().count} cajas o bultos"><span class="cart-icon">${icon('bag')}<span class="count">${calc().count}</span></span><span class="tool-text"><small>Tu pedido</small><strong>${money(calc().subtotal)}</strong></span></button></div></div><nav class="navigation" aria-label="Navegación principal"><div class="nav-inner"><div class="nav-links">${[['/','Inicio'],['/tienda','Catálogo mayorista'],['/como-comprar','Cómo comprar'],['/nosotros','Sobre nosotros'],['/contacto','Contacto']].map(([p,t])=>`<a href="#${p}" class="${path===p?'active':''}">${t}</a>`).join('')}</div><button class="wholesale-link link-button" data-action="whatsapp-contact">${icon('phone')}Consultar por WhatsApp</button></div></nav></div></header>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-grid"><div>${brand()}<p>Productos envasados para abastecer heladerías. Venta por caja o bulto.</p><div class="footer-note">${icon('box')}Un único precio mayorista</div></div><div><h4>Tu próximo pedido</h4><div class="footer-links"><a href="#/tienda">Catálogo mayorista</a><a href="#/como-comprar">Cómo comprar</a><a href="#/carrito">Consultar stock del pedido</a><a href="#/cuenta?tab=pedidos">Mis pedidos</a></div></div><div><h4>Información</h4><div class="footer-links"><a href="#/contacto">Contacto</a><a href="#/ayuda">Preguntas frecuentes</a><a href="#/legal">Condiciones de la demostración</a><a href="/proyecto-montevideana-demo.zip" download>Código y documentación</a></div></div><div><h4>Operación de prueba</h4><div class="footer-links"><span>Pago anticipado requerido.</span><span>Entrega a coordinar por WhatsApp.</span><a href="#/admin">Explorar panel DEMO</a><button class="text-link link-button" data-action="demo-info">Estado de esta versión</button></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} La Montevideana</span><span>DEMO · Fotos y logo suministrados. Precios, stock y contenido por caja/bulto pendientes.</span></div></div></footer>`}
function mobileNav(){const{path}=route();return `<nav class="mobile-nav" aria-label="Accesos móviles"><a href="#/" class="${path==='/'?'active':''}">${icon('home')}Inicio</a><a href="#/tienda" class="${path==='/tienda'?'active':''}">${icon('box')}Catálogo</a><a href="#/como-comprar" class="${path==='/como-comprar'?'active':''}">${icon('info')}Cómo pedir</a><button data-action="cart">${icon('bag')}Pedido (${calc().count})</button><a href="#/cuenta" class="${path==='/cuenta'?'active':''}">${icon('user')}Mi cuenta</a></nav>`}
function crumb(label){return `<div class="breadcrumb"><a href="#/">Inicio</a>${icon('chevron')}<span>${esc(label)}</span></div>`}
function pageHead(title,desc=''){return `<div class="page-title"><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>`}
function notice(text,type=''){return `<div class="notice ${type}">${icon('info')}<div>${text}</div></div>`}
function empty(title,desc,link='/tienda',label='Explorar catálogo',i='box'){return `<div class="empty">${icon(i)}<h3>${title}</h3><p>${desc}</p>${link?`<a class="btn" href="#${link}">${label}</a>`:''}</div>`}
function sectionTitle(kicker,title,desc,link,label){return `<div class="section-head"><div>${kicker?`<div class="section-kicker">${kicker}</div>`:''}<h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${link?`<a class="text-link" href="#${link}">${label||'Ver catálogo'}</a>`:''}</div>`}
function productCard(p){return `<article class="product"><button class="fav ${state.favorites.includes(p.id)?'selected':''}" data-action="favorite" data-id="${p.id}" aria-label="${state.favorites.includes(p.id)?'Quitar de':'Agregar a'} favoritos: ${esc(p.name)}" aria-pressed="${state.favorites.includes(p.id)}">${icon('heart')}</button><a class="product-image" href="#/producto/${p.id}"><img src="${esc(p.image)}" alt="${p.provisional?'Imagen pendiente: ':''}${esc(p.name)}" loading="lazy" width="600" height="480"></a><div class="product-body"><div class="product-brand">${esc(p.family||'VENTA POR '+p.saleUnit.toUpperCase())}</div><h3><a href="#/producto/${p.id}">${esc(p.name)}</a></h3><div class="product-size">${esc(p.size)}</div><div class="product-bottom"><div class="price"><strong>${money(p.price)}</strong><small>${p.price===0?'Precio pendiente de carga':'Precio mayorista por '+saleLabel(p)}</small></div><button class="add" data-action="add" data-id="${p.id}" ${p.stock===0?'disabled':''} aria-label="Agregar ${esc(p.name)} al pedido">${icon('plus')}${p.stock===0?'Sin stock':'Agregar'}</button></div><button class="stock-link" data-action="stock-inquiry" data-id="${p.id}">${icon('phone')}Consultar stock</button></div></article>`}
function home(){return `<section class="hero"><div class="container hero-inner"><div class="hero-copy"><div class="eyebrow">PARA HELADERÍAS Y COMERCIOS</div><h1>Tu heladería.<br>Bien <em>abastecida.</em></h1><p>Productos envasados por caja o bulto.<br>Armá tu pedido online y coordiná la entrega con nosotros.</p><div class="hero-actions"><a class="btn" href="#/tienda">Ver catálogo mayorista</a><a class="btn secondary" href="#/como-comprar">Cómo comprar</a></div><div class="hero-note"><span>${icon('box')}Solo venta mayorista</span><span>${icon('shield')}Pago previo al despacho</span></div></div><div class="hero-visual wholesale-visual"><div class="pack-illustration"><img src="/assets/productos/lm-007.webp" alt="Helado Súper DDL con merengues de La Montevideana, venta por bulto" width="1485" height="1357" fetchpriority="high"><img src="/assets/productos/lm-001.webp" alt="Postre helado almendrado de La Montevideana, venta por caja" width="1222" height="846"></div><div class="floating-label"><span class="round">${icon('store')}</span><div><strong>La Montevideana</strong><small>Distribución mayorista</small></div></div></div></div></section><section class="benefits" aria-label="Cómo trabajamos"><div class="container benefits-inner">${[['box','Por caja o bulto','Productos envasados'],['phone','Consultá stock','Antes de confirmar tu pedido'],['shield','Pago anticipado','Antes de preparar y despachar'],['truck','Entrega coordinada','Costo, día y hora por WhatsApp']].map(([i,t,d])=>`<div class="benefit">${icon(i)}<div><strong>${t}</strong><small>${d}</small></div></div>`).join('')}</div></section><div class="container"><section class="section">${sectionTitle('CONOCÉ NUESTROS PRODUCTOS','Productos para tu comercio','Fotografías originales. Nombres orientativos y precios pendientes de carga.','/tienda','Ver todos los productos')}${notice('Catálogo con las 50 imágenes recibidas. Las cantidades por caja o bulto están por confirmar y los precios $0 están pendientes de carga; no indican productos gratuitos.')}<div class="product-grid">${state.products.filter(p=>p.active&&p.featured).slice(0,4).map(productCard).join('')}</div></section><section class="section">${sectionTitle('UNA COMPRA BIEN ORGANIZADA','Online para pedir. WhatsApp para coordinar.','Cada paso, en el lugar que corresponde.')}<div class="info-grid">${[['box','Armá tu pedido','Elegí productos y cantidades de cajas o bultos dentro de la página.'],['phone','Consultá antes','Verificá disponibilidad por WhatsApp con el detalle de tu selección.'],['shield','Pagá antes del despacho','El pago debe estar acreditado. La entrega se acuerda por WhatsApp.']].map(([i,t,d])=>`<article class="info-card">${icon(i)}<h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section class="wholesale-banner"><div><div class="section-kicker">COORDINACIÓN DIRECTA</div><h2>La entrega la acordamos con vos.</h2><p>Costo, día y horario se coordinan por WhatsApp. No se calculan como envío gratuito ni se confirman automáticamente en la página.</p></div><button class="btn white" data-action="whatsapp-contact">Consultar por WhatsApp</button></section></div>`}
function catalog(){const{params}=route();const cat=params.get('cat')||'todos',q=params.get('q')||'',sort=params.get('sort')||'name',family=params.get('family')||'';let list=state.products.filter(p=>p.active);if(cat!=='todos')list=list.filter(p=>p.category===cat);if(family)list=list.filter(p=>p.family===family);if(q){const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();list=list.filter(p=>norm([p.name,p.brand,p.flavor,p.size,p.family||''].join(' ')).includes(norm(q)))}if(params.get('available'))list=list.filter(p=>p.stock!==0);list.sort(sort==='price-asc'?(a,b)=>a.price-b.price:sort==='price-desc'?(a,b)=>b.price-a.price:(a,b)=>a.name.localeCompare(b.name,'es'));return `<div class="container">${crumb('Catálogo mayorista')}${pageHead('Productos para tu heladería.','Un único precio mayorista por presentación. La cantidad seleccionada representa cajas o bultos completos.')}${notice('Los precios se muestran en $0 hasta su carga. Las fotos corresponden a los archivos recibidos. La cantidad de unidades y el contenido por caja o bulto están pendientes de confirmación.')}<div class="chips">${categories.map(c=>`<a class="chip ${cat===c.id?'active':''}" href="#/tienda${c.id!=='todos'?'?cat='+c.id:''}">${c.name}</a>`).join('')}</div><div class="catalog-layout"><aside class="filters"><h3>Buscá tu producto</h3><form data-form="filters"><input type="hidden" name="cat" value="${esc(cat)}">${field('Nombre o sabor','q',q,'text',false,'Buscar en el catálogo')}<label class="field"><span>Presentación</span><select name="presentation"><option value="">Todas</option><option value="cajas" ${cat==='cajas'?'selected':''}>Por caja</option><option value="bultos" ${cat==='bultos'?'selected':''}>Por bulto</option></select></label><label class="field"><span>Tipo de producto</span><select name="family"><option value="">Todos los tipos</option>${[...new Set(state.products.filter(p=>p.active&&p.family).map(p=>p.family))].sort().map(f=>`<option ${f===family?'selected':''}>${esc(f)}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="available" value="1" ${params.get('available')?'checked':''}>Ocultar agotados informados</label><button class="btn small full">Aplicar filtros</button><a href="#/tienda" class="text-link clear-filters">Limpiar filtros</a></form></aside><div class="catalog-main"><div class="results-bar"><span>${list.length} productos</span><label>Ordenar <select data-change="sort" aria-label="Ordenar productos">${[['name','Nombre A–Z'],['price-asc','Menor precio'],['price-desc','Mayor precio']].map(([v,t])=>`<option value="${v}" ${sort===v?'selected':''}>${t}</option>`).join('')}</select></label></div>${list.length?`<div class="product-grid">${list.slice(0,pageLimit).map(productCard).join('')}</div>${list.length>pageLimit?'<div class="load-more"><button class="btn secondary" data-action="load">Ver más productos</button></div>':''}`:empty('No encontramos ese producto.','Probá otro nombre o presentación.')}</div></div></div>`}
function detail(id){const p=state.products.find(p=>p.id===id&&p.active);if(!p)return `<div class="container">${crumb('Producto no disponible')}${empty('Producto no disponible.','Volvé al catálogo para elegir otra presentación.')}</div>`;return `<div class="container">${crumb(p.name)}<div class="product-detail"><div class="detail-photo"><img src="${esc(p.image)}" alt="${esc(p.name)}" width="600" height="480"><small>${p.provisional?'Imagen de producto pendiente de incorporar.':'Imagen suministrada. Puede representar una unidad; la venta es por caja o bulto.'}</small></div><div class="detail-info"><div class="product-brand">VENTA MAYORISTA · POR ${esc(p.saleUnit.toUpperCase())}</div><h1>${esc(p.name)}</h1><div class="product-size">${esc(p.size)}</div><div class="price"><strong>${money(p.price)}</strong><small>${p.price===0?'Precio pendiente de carga. No es un producto gratuito.':'Precio mayorista por '+saleLabel(p)+' · ARS'}</small></div><div class="stock ${p.stock===0?'out':''}">${stockLabel(p)}</div><p>${esc(p.description)}</p><form data-form="add-product" data-id="${p.id}" class="purchase-row"><div class="quantity"><button type="button" data-action="detail-minus" aria-label="Reducir cantidad">${icon('minus')}</button><input id="detail-qty" name="qty" type="number" aria-label="Cantidad de ${saleLabel(p,2)}" min="1" max="${p.stock===null?9999:p.stock||1}" value="1" required><button type="button" data-action="detail-plus" aria-label="Aumentar cantidad">${icon('plus')}</button></div><button class="btn" ${p.stock===0?'disabled':''}>Agregar al pedido</button></form><p class="fine">Cada cantidad equivale a 1 ${saleLabel(p)} completo. No a una unidad suelta.</p><button class="btn secondary full" data-action="stock-inquiry" data-id="${p.id}">${icon('phone')}Consultar stock antes de confirmar</button><div class="detail-meta mt"><div>${icon('shield')} Pago<strong>Anticipado, antes de despachar</strong></div><div>${icon('truck')} Entrega<strong>Costo, día y hora por WhatsApp</strong></div></div></div></div>${notice('La consulta no reserva stock. Ingredientes, alérgenos, contenido y conservación deben confirmarse con la ficha del producto antes de operar comercialmente.')}</div>`}
function quantity(p){return `<div class="quantity"><button data-action="qty" data-id="${p.id}" data-delta="-1" aria-label="Reducir cantidad de ${esc(p.name)}">${icon('minus')}</button><span>${p.qty}</span><button data-action="qty" data-id="${p.id}" data-delta="1" aria-label="Aumentar cantidad de ${esc(p.name)}">${icon('plus')}</button></div>`}
function cartLines(){return calc().lines.map(p=>`<div class="cart-line"><a href="#/producto/${p.id}" data-action="close-link"><img src="${esc(p.image)}" alt="${esc(p.name)}"></a><div class="cart-line-content"><h3>${esc(p.name)}</h3><small>${p.qty} ${saleLabel(p,p.qty)} · ${money(p.price)} por ${saleLabel(p)}</small><div class="cart-line-actions">${quantity(p)}<button class="icon-btn" data-action="remove" data-id="${p.id}" aria-label="Quitar ${esc(p.name)}">${icon('trash')}</button></div>${p.stock!==null&&p.qty>p.stock?'<p class="inline-error">La cantidad supera el stock informado. Revisá el pedido.</p>':''}</div><strong class="line-price">${money(p.total)}</strong></div>`).join('')}
function summary(){const t=calc();return `<div class="summary-row"><span>Productos (${t.count} cajas/bultos)</span><strong>${money(t.subtotal)}</strong></div><div class="summary-row delivery-pending"><span>Costo de entrega</span><strong>A coordinar por WhatsApp</strong></div><div class="summary-row"><span>Día y horario de entrega</span><strong>A coordinar</strong></div><div class="summary-row total"><span>Subtotal de productos</span><strong>${money(t.subtotal)}</strong></div><p class="summary-note">${t.pricesPending?'Hay precios pendientes de cargar. El subtotal no es un importe cobrable.':'El subtotal no incluye la entrega. Su costo se acuerda por WhatsApp.'} Pago acreditado requerido antes del despacho.</p>`}
function cartPage(){const t=calc();return `<div class="container">${crumb('Tu pedido')}${pageHead('Armá tu pedido mayorista.','Revisá productos y cantidades por caja o bulto antes de continuar.')}${t.missingProducts?notice('Tu selección conserva referencias anteriores que ya no forman parte del catálogo. Quitalas para elegir productos de las imágenes recibidas.')+'<button class="btn secondary" data-action="clear-old-cart">Quitar referencias anteriores</button>':''}${!t.count?empty('Tu pedido está vacío.','Elegí productos para abastecer tu heladería.'):`<div class="two-columns"><div><div class="panel">${cartLines()}</div><div class="panel"><h2>¿Querés consultar stock primero?</h2><p class="fine">Prepará una consulta de WhatsApp con todos los productos y cantidades. La disponibilidad se confirma con el negocio; no se supone por abrir el chat.</p><button class="btn secondary full" data-action="stock-inquiry">${icon('phone')}Consultar stock del pedido</button></div><a class="text-link" href="#/tienda">Seguir agregando productos</a></div><aside><section class="panel"><h2>Resumen mayorista</h2>${summary()}<a class="btn full" href="#/checkout">Continuar dentro de la página</a></section>${notice('Por ahora solo podés guardar una solicitud DEMO. No hay cobros activos ni entregas confirmadas.','warning')}</aside></div>`}</div>`}
function field(label,name,value='',type='text',required=false,placeholder=''){return `<label class="field"><span>${esc(label)}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} placeholder="${esc(placeholder)}" ${type==='number'?'min="0" step="1"':''} maxlength="150"></label>`}
function checkout(){const t=calc(),p=state.profile||{};if(!t.count)return `<div class="container">${crumb('Datos del pedido')}${empty('Tu pedido está vacío.','Agregá productos para continuar.')}</div>`;return `<div class="container">${crumb('Datos del pedido')}${pageHead('Tu pedido se inicia acá.','La entrega y su costo se coordinan después por WhatsApp. El pago debe estar acreditado antes del despacho.')}${notice('Versión DEMO. Los $0 son precios pendientes de cargar. Guardar esta solicitud no confirma una compra gratuita, no acredita pagos y no reserva stock.','warning')}<form data-form="checkout"><div class="two-columns"><div><section class="panel"><h2>Datos de tu comercio · DEMO</h2><div class="form-grid">${field('Nombre de contacto ficticio','name',p.name||'','text',true,'Ej.: Cliente DEMO')}${field('Comercio de ejemplo','business',p.business||'','text',true,'Ej.: Heladería DEMO')}${field('Correo de ejemplo','email',p.email||'','email',true,'cliente@example.invalid')}${field('Referencia de contacto DEMO','contact','','text',true,'CLIENTE-DEMO-01')}</div><label class="field"><span>Observaciones (opcional)</span><textarea name="notes" maxlength="500" placeholder="Observaciones de ejemplo"></textarea></label></section><section class="panel"><h2>Consulta previa de stock</h2><p class="fine">Antes de guardar el pedido podés consultar la disponibilidad de las cajas o bultos que elegiste.</p><button type="button" class="btn secondary" data-action="stock-inquiry">${icon('phone')}Consultar stock por WhatsApp</button><p class="fine">La página no toma esta consulta como una confirmación de disponibilidad.</p></section><section class="panel"><h2>Pago anticipado</h2><p>El pedido debe pagarse antes de su preparación y despacho.</p><p class="fine">${t.pricesPending?'Primero deberán cargarse los precios. Mientras figuren en $0 no se genera ningún cobro.':'Los pagos online requieren configurar y verificar el proveedor de pagos.'} No hay pago contra entrega ni aprobación automática de pago.</p><span class="pill orange">Pago pendiente · Cobros deshabilitados</span></section><section class="panel"><h2>Entrega por WhatsApp</h2><p class="fine">El costo, día y horario se acuerdan con La Montevideana. Esta página no asigna turnos ni considera la entrega sin cargo.</p><strong>Costo de entrega: pendiente de coordinación.</strong></section></div><aside><section class="panel"><h2>Tu selección</h2>${t.lines.map(l=>`<div class="summary-row"><span>${l.qty} ${saleLabel(l,l.qty)} de ${esc(l.name)}</span><strong>${money(l.total)}</strong></div>`).join('')}${summary()}<label class="check"><input type="checkbox" name="consent" required>Entiendo que guardo una solicitud DEMO, sin compra, pago ni entrega confirmados.</label><button class="btn full">Guardar solicitud DEMO</button></section><div id="checkout-error" class="inline-error" role="alert"></div></aside></div></form></div>`}
function statusPill(status){return `<span class="pill ${status==='Cancelado DEMO'?'red':'orange'}">${esc(status)}</span>`}
function confirmation(id){const o=state.orders.find(o=>o.id===id);if(!o)return `<div class="container">${crumb('Pedido')}${empty('Solicitud no encontrada en este navegador.','Los datos de esta demo se guardan localmente.','/cuenta?tab=pedidos','Ver mis solicitudes')}</div>`;return `<div class="container">${crumb('Solicitud DEMO')}<div class="success"><div class="success-icon">${icon('check')}</div><h1>Tu solicitud DEMO está guardada.</h1><p class="muted">La compra todavía no está confirmada. El pago sigue pendiente.<br>No se reservó stock ni se acordó una entrega.</p><section class="panel"><div class="order-header"><h3>${esc(o.number)}</h3>${statusPill(o.status)}</div><p class="fine">${date(o.created)}</p>${o.lines.map(l=>`<div class="summary-row"><span>${l.qty} ${saleLabel(l,l.qty)} · ${esc(l.name)}</span><strong>${money(l.total)}</strong></div>`).join('')}<div class="summary-row total"><span>Subtotal de productos</span><strong>${money(o.subtotal)}</strong></div><p class="fine">${o.pricesPending?'Precios pendientes de carga. No es un pedido gratuito.':'Importe de productos, sin incluir entrega.'}<br>Pago: pendiente, no procesado.<br>Entrega: costo, día y horario a coordinar por WhatsApp.</p></section><div class="hero-actions"><button class="btn" data-action="delivery-inquiry" data-id="${o.id}">${icon('phone')}Coordinar entrega por WhatsApp</button><a class="btn secondary" href="#/cuenta?tab=pedidos">Ver mis solicitudes</a></div></div></div>`}
function orderCard(o,admin=false){return `<article class="order-card"><div class="order-header"><div><h3><a href="#/pedido/${o.id}">${esc(o.number)}</a></h3><small class="muted">${date(o.created)}</small></div>${statusPill(o.status)}</div><p class="order-items">${o.lines.map(l=>`${l.qty} ${saleLabel(l,l.qty)} · ${esc(l.name)}`).join('<br>')}</p>${admin?`<p class="fine">${esc(o.customer.business)} · ${esc(o.customer.name)}<br>${esc(o.customer.email)}<br>Referencia: ${esc(o.customer.contact)}${o.customer.notes?'<br>Observaciones: '+esc(o.customer.notes):''}</p>`:''}<p class="fine">Pago: pendiente, no procesado. ${o.pricesPending?'Precios pendientes de carga.':''}<br>Entrega: costo, día y horario a coordinar por WhatsApp.</p><div class="order-footer"><strong>${money(o.subtotal)} <small>productos</small></strong>${admin?`<label class="field"><span>Estado del pedido</span><select data-change="order-status" data-id="${o.id}">${['Pendiente de precio DEMO','Pendiente de pago DEMO','En preparación DEMO','En reparto DEMO','Entregado DEMO','Cancelado DEMO'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></label>`:`<button class="btn small secondary" data-action="reorder" data-id="${o.id}">${icon('repeat')}Repetir selección</button>`}</div><button class="stock-link" data-action="delivery-inquiry" data-id="${o.id}">${icon('phone')}Coordinar entrega por WhatsApp</button></article>`}
function account(){const tab=route().params.get('tab')||'perfil';let content='';if(tab==='favoritos'){const list=state.products.filter(p=>p.active&&state.favorites.includes(p.id));content=list.length?`<div class="product-grid">${list.map(productCard).join('')}</div>`:empty('Guardá tus productos habituales.','Marcá el corazón de un producto para encontrarlo acá.')}else if(tab==='pedidos'){const list=state.profile?state.orders.filter(o=>o.customer.email===state.profile.email):state.orders;content=list.length?list.map(o=>orderCard(o)).join(''):empty('Todavía no hay solicitudes.','Armá una selección para probar el recorrido mayorista.')}else content=`<div class="two-columns"><form class="panel" data-form="profile"><h2>Tu comercio · DEMO</h2><p class="fine">Perfil local de prueba, sin contraseña ni cuenta comercial activa. Usá datos ficticios.</p>${field('Nombre de contacto','name',state.profile?.name||'','text',true)}${field('Comercio de ejemplo','business',state.profile?.business||'','text',true)}${field('Correo de ejemplo','email',state.profile?.email||'','email',true,'cliente@example.invalid')}<button class="btn">Guardar perfil DEMO</button>${state.profile?'<button type="button" class="btn small secondary" data-action="logout">Cerrar perfil</button>':''}</form><section class="panel"><h2>Una sola modalidad: por mayor.</h2><p class="fine">Todos los productos tienen un único precio por caja o bulto. No hay lista minorista, aprobación mayorista ni escalas de precios distintas.</p><p class="fine">Los favoritos y las solicitudes se guardan en este navegador. No se sincronizan con otros dispositivos.</p><div class="row"><button class="btn small secondary" data-action="export-backup">Exportar datos DEMO</button><button class="btn small secondary" data-action="reset">Restablecer DEMO</button></div></section></div>`;return `<div class="container">${crumb('Mi cuenta')}${pageHead('Tu comercio, a mano.','Favoritos y solicitudes de prueba para preparar tu próximo pedido.')}${notice('Esta versión guarda datos solo en tu navegador. La autenticación comercial y la base compartida todavía no están integradas.')}<nav class="tabs" aria-label="Secciones de cuenta">${[['perfil','Mi comercio'],['pedidos','Mis solicitudes'],['favoritos','Favoritos']].map(([v,t])=>`<a class="tab ${tab===v?'active':''}" href="#/cuenta?tab=${v}">${t}</a>`).join('')}</nav>${content}</div>`}
function adminNav(tab){return `<nav class="admin-nav" aria-label="Módulos administrativos">${[['dashboard','grid','Resumen'],['productos','box','Productos'],['pedidos','bag','Pedidos'],['clientes','user','Clientes'],['inventario','chart','Inventario'],['configuracion','settings','Configuración'],['actividad','clock','Actividad']].map(([id,i,t])=>`<a href="#/admin${id==='dashboard'?'':'/'+id}" class="${id===tab?'active':''}">${icon(i)}${t}</a>`).join('')}</nav>`}
function admin(){const tab=route().path.split('/')[2]||'dashboard';let content='';if(tab==='dashboard'){content=`<div class="admin-toolbar"><h2>Resumen mayorista</h2><a class="text-link" href="#/tienda">Ver catálogo</a></div><div class="stats">${[['box','Productos',state.products.filter(p=>p.active).length],['bag','Solicitudes DEMO',state.orders.length],['tag','Precios pendientes',state.products.filter(p=>p.price===0).length],['shield','Pagos acreditados',0]].map(([i,t,v])=>`<div class="stat">${icon(i)}<small>${t}</small><strong>${v}</strong></div>`).join('')}</div><section class="panel"><h3>Estado de la integración</h3><p class="fine">Logo e imágenes originales: incorporados. 50 referencias con nombres orientativos y precios pendientes de carga. WhatsApp: ${state.settings.whatsapp?'número configurado':'pendiente de número comercial'}. Pagos: deshabilitados.</p><p class="fine">No se prepara ni despacha un pedido sin pago acreditado. Esta versión no acredita pagos.</p></section><section class="panel"><h3>Actividad reciente</h3>${state.audit.slice(0,8).map(a=>`<p class="fine">${date(a.at)} · ${esc(a.action)}</p>`).join('')||'<p class="fine">Todavía no hay modificaciones.</p>'}</section>`}
else if(tab==='productos'){content=`<div class="admin-toolbar"><h2>Productos por caja o bulto</h2><button class="btn small" data-action="edit-product" data-id="new">${icon('plus')}Nuevo producto</button></div><div class="table-wrap"><table><thead><tr><th>PRODUCTO</th><th>PRECIO MAYORISTA</th><th>PRESENTACIÓN</th><th>ESTADO</th><th>ACCIÓN</th></tr></thead><tbody>${state.products.map(p=>`<tr><td><img src="${esc(p.image)}" alt="">${esc(p.name)}</td><td>${money(p.price)}${p.price===0?'<div class="fine">Pendiente</div>':''}</td><td>Por ${saleLabel(p)}</td><td>${p.active?'Activo':'Inactivo'}</td><td><button class="btn small secondary" data-action="edit-product" data-id="${p.id}">Editar</button></td></tr>`).join('')}</tbody></table></div>`}
else if(tab==='pedidos'){content=`<div class="admin-toolbar"><h2>Solicitudes y pedidos DEMO</h2><button class="btn small secondary" data-action="export-orders">Exportar CSV</button></div>${notice('Ningún pedido de esta demo tiene un pago acreditado. Los estados de preparación, reparto y entrega están bloqueados mientras el pago esté pendiente. No se descuenta stock por guardar una solicitud.','warning')}${state.orders.length?state.orders.map(o=>orderCard(o,true)).join(''):empty('Sin solicitudes de prueba.','Armá un pedido desde el catálogo.')}`}
else if(tab==='clientes'){content=`<section class="panel"><h2>Clientes mayoristas</h2><p>La modalidad es única: venta mayorista por caja o bulto.</p>${state.profile?`<h3>${esc(state.profile.business)}</h3><p class="fine">${esc(state.profile.name)} · ${esc(state.profile.email)}</p>`:'<p class="fine">Todavía no hay un perfil DEMO creado.</p>'}<p class="fine">No se requiere una aprobación para acceder a una segunda lista de precios: todos usan el mismo precio del producto.</p></section>`}
else if(tab==='inventario'){content=`<div class="admin-toolbar"><h2>Inventario por presentación</h2><div class="actions"><button class="btn small secondary" data-action="export-inventory">Exportar CSV</button><label class="btn small secondary" for="csv-file">Importar CSV</label><input id="csv-file" type="file" accept=".csv,text/csv" class="hide" data-change="import-inventory"></div></div>${notice('Stock vacío significa “a consultar”, no agotado. Las cantidades corresponden a cajas o bultos completos. CSV: columnas id y stock; dejá stock vacío si no se confirmó.')}<div class="table-wrap"><table><thead><tr><th>PRODUCTO</th><th>PRESENTACIÓN</th><th>STOCK DEMO</th><th>ACCIÓN</th></tr></thead><tbody>${state.products.map(p=>`<tr><td>${esc(p.name)}<div class="fine">${p.id}</div></td><td>${saleLabel(p,p.stock===1?1:2)}</td><td>${p.stock===null?'A consultar':p.stock}</td><td><button class="btn small secondary" data-action="stock-adjust" data-id="${p.id}">Ajustar</button></td></tr>`).join('')}</tbody></table></div>`}
else if(tab==='configuracion'){content=`<form class="panel" data-form="settings"><h2>Configuración comercial</h2>${field('WhatsApp comercial con código de país','whatsapp',state.settings.whatsapp,'tel',false,'Ej.: código de país + número, sin inventar un contacto')}<p class="fine">Si está vacío, las consultas solo preparan un texto para copiar. Nunca se envía un mensaje automáticamente.</p><div class="form-grid">${field('Dirección','address',state.settings.contact.address,'text',true)}${field('Horarios','hours',state.settings.contact.hours,'text',true)}</div><button class="btn">Guardar configuración</button></form><section class="panel"><h3>Identidad visual</h3><p class="fine">Logo suministrado incorporado sin modificaciones. Paleta extraída del archivo: azul #003796, rojo #D10F11 y blanco. Las imágenes están vinculadas a IDs estables de producto.</p></section><section class="panel"><h3>Reglas confirmadas</h3><p>Precio único mayorista. Venta por caja o bulto. Pago anticipado. Entrega a coordinar por WhatsApp.</p><p class="fine">No se configuran tarifas fijas, turnos automáticos ni pago contra entrega. Credenciales de pago y permisos comerciales deben integrarse en el servidor.</p></section>`}
else if(tab==='actividad'){content=`<div class="admin-toolbar"><h2>Actividad DEMO</h2><button class="btn small secondary" data-action="export-audit">Exportar CSV</button></div><div class="table-wrap"><table><thead><tr><th>FECHA</th><th>PERFIL</th><th>ACCIÓN</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${date(a.at)}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td></tr>`).join('')||'<tr><td colspan="3">Sin actividad.</td></tr>'}</tbody></table></div>`}
else content=notice('Este módulo ya no aplica a la modalidad de precio único.');return `<div class="container">${crumb('Panel DEMO')}${pageHead('Gestión de La Montevideana.','Catálogo, pedidos y stock por caja o bulto.')}${notice('Panel local de demostración, sin permisos comerciales de servidor. Los cambios solo afectan este navegador.','warning')}<div class="admin-layout">${adminNav(tab)}<div style="min-width:0">${content}</div></div></div>`}
function howTo(){return `<div class="container">${crumb('Cómo comprar')}${pageHead('Un pedido mayorista, paso a paso.','Las compras se inician en la página. La entrega se coordina directamente por WhatsApp.')}<div class="info-grid">${[['box','Elegí cajas o bultos','Armá tu pedido con productos envasados. No se venden porciones de heladería ni unidades sueltas.'],['phone','Consultá stock si lo necesitás','Desde el producto o el carrito podés preparar un mensaje con las cantidades antes de confirmar.'],['bag','Completá el pedido online','Ingresá los datos de tu comercio en la página. En esta demo solo se guarda una solicitud local.'],['shield','Pagá por anticipado','El pedido debe estar pagado antes de la preparación y el despacho. Los cobros aún no están habilitados.'],['truck','Acordá la entrega','El costo, el día y el horario se definen por WhatsApp. El subtotal web no incluye un costo de entrega inventado.']].map(([i,t,d])=>`<section class="info-card">${icon(i)}<h3>${t}</h3><p>${d}</p></section>`).join('')}</div>${notice('Por ahora los precios se muestran en $0, pendientes de carga. No indican productos gratuitos. Esta versión no confirma compras, pagos ni entregas.','warning')}<a class="btn" href="#/tienda">Armar mi selección</a></div>`}
function about(){return `<div class="container">${crumb('Sobre nosotros')}${pageHead('La Montevideana.','Distribución mayorista para heladerías y comercios.')}<section class="panel"><h2>Productos envasados para abastecer tu negocio.</h2><p>La Montevideana distribuye productos por caja o bulto. Esta tienda está pensada para que puedas consultar el catálogo y armar tu pedido online.</p><p>La entrega se coordina por WhatsApp y requiere pago previo al despacho.</p><p class="fine">El logo y las fotografías originales están incorporados. Los datos institucionales adicionales están pendientes de confirmar. No se atribuyen años de trayectoria ni certificaciones no confirmados.</p></section></div>`}
function contact(){return `<div class="container">${crumb('Contacto')}${pageHead('Coordinemos tu próximo pedido.','Stock y entrega se consultan directamente con La Montevideana.')}<div class="contact-grid"><section class="panel"><h2>WhatsApp comercial</h2><p>${state.settings.whatsapp?esc(state.settings.whatsapp):'Número pendiente de configuración.'}</p><button class="btn" data-action="whatsapp-contact">${icon('phone')}Preparar consulta por WhatsApp</button><p class="fine">La consulta se abre para que la revises. No se envía automáticamente.</p><h3 class="mt">Datos comerciales</h3><p class="fine">${esc(state.settings.contact.address)}<br>${esc(state.settings.contact.hours)}</p></section><section class="panel"><h2>Sobre la entrega</h2><p>El costo, día y horario se acuerdan por WhatsApp.</p><p>El pedido debe estar pagado con anterioridad al despacho.</p><button class="btn secondary" data-action="stock-inquiry">Consultar stock del pedido</button></section></div></div>`}
function help(){return `<div class="container legal">${crumb('Ayuda')}${pageHead('Antes de hacer tu pedido.')}<div class="faq">${[['¿Se venden helados por unidad o porción?','No. La Montevideana distribuye productos envasados por caja o bulto para heladerías.'],['¿Por qué todos los precios figuran en $0?','Están pendientes de carga. No son productos gratuitos. La página no genera un cobro de $0 ni aprueba el pedido como pagado.'],['¿Hay precio minorista y precio mayorista?','Hay un único precio mayorista por presentación. No se requiere una aprobación para obtener otra lista de precios.'],['¿Puedo consultar stock antes de confirmar?','Sí. Usá Consultar stock desde un producto o desde el carrito. Se prepara un mensaje con productos y cantidades. Si falta el número de WhatsApp, podés copiar el texto; no se simula una consulta enviada.'],['¿Dónde se coordina la entrega?','Por WhatsApp, incluyendo el costo, el día y el horario. La página no promete entrega gratuita ni asigna turnos.'],['¿Puedo pagar al recibir?','No. El pago debe acreditarse antes del despacho. En la versión DEMO los cobros están deshabilitados y todos los pagos quedan pendientes.'],['¿La solicitud DEMO es una compra confirmada?','No. Se guarda solo en este navegador y no se envía al negocio, no reserva stock ni acredita un pago.'],['¿Las fotos muestran una unidad o la caja completa?','Las imágenes recibidas pueden mostrar un producto individual. La venta se realiza por caja o bulto completo. La cantidad exacta por presentación está pendiente de confirmar; no se deduce del número de unidades visibles en la foto.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div>`}
function legal(){return `<div class="container legal">${crumb('Condiciones DEMO')}${pageHead('Información clara antes de avanzar.')}${notice('Versión de demostración. No habilitada para ventas reales.','warning')}<h2>Precios y modalidad</h2><p>Un único precio mayorista por caja o bulto. Los $0 son valores pendientes de carga y no ofertas gratuitas. El catálogo usa las 50 imágenes recibidas. Los nombres son orientativos y el contenido por caja o bulto aún debe confirmarse.</p><h2>Pago y entrega</h2><p>Se requiere pago anticipado. No hay proveedor de pagos activo. El costo, día y horario de entrega se acuerdan por WhatsApp y no forman parte del subtotal de productos.</p><h2>Datos de prueba</h2><p>Perfiles, pedidos y modificaciones se guardan solo en el navegador. No ingreses datos personales reales. Podés exportarlos o eliminarlos desde Mi cuenta. La plataforma de alojamiento gestiona el acceso privado y puede registrar datos técnicos.</p><h2>Preparación comercial</h2><p>La puesta en marcha requiere base compartida, autorización de servidor, pagos verificados, política de privacidad, condiciones comerciales y logísticas confirmadas, revisión de normativa argentina y fichas de productos.</p></div>`}
function render(){const{path}=route();const views={'/':home,'/tienda':catalog,'/carrito':cartPage,'/checkout':checkout,'/cuenta':account,'/como-comprar':howTo,'/mayoristas':howTo,'/ofertas':howTo,'/nosotros':about,'/contacto':contact,'/ayuda':help,'/legal':legal};const body=views[path]?views[path]():path.startsWith('/producto/')?detail(path.split('/')[2]):path.startsWith('/pedido/')?confirmation(path.split('/')[2]):path.startsWith('/admin')?admin():`<div class="container">${crumb('Página no encontrada')}${empty('No encontramos esta página.','Volvé al catálogo.')}</div>`;$('#app').innerHTML=header()+(!storageOK?'<div class="storage-warning">No se pudo guardar. Los cambios pueden perderse.</div>':'')+`<main id="main" tabindex="-1" class="${path==='/'?'':'page-body'}">${body}</main>`+footer()+mobileNav();document.title='La Montevideana · '+(path.startsWith('/admin')?'Panel DEMO':'Distribución mayorista')}
function sync(){save();render();if(drawerOpen)drawCart(false)}
function add(id,qty=1){const p=state.products.find(p=>p.id===id&&p.active);if(!p||p.stock===0){toast('Producto sin stock informado.');return}const line=state.cart.find(l=>l.id===id),old=line?.qty||0,limit=p.stock===null?9999:p.stock,next=Math.min(old+qty,limit);if(next===old){toast('Llegaste al stock informado.');return}if(line)line.qty=next;else state.cart.push({id,qty:next});sync();toast('Agregado: '+next+' '+saleLabel(p,next)+' de '+p.name+'.')}
function closeOverlay(){const was=$('#overlay').innerHTML;$('#overlay').innerHTML='';document.body.style.overflow='';drawerOpen=false;if(was&&returnFocus?.isConnected)returnFocus.focus()}
function overlay(html){returnFocus=document.activeElement;$('#overlay').innerHTML=`<div class="overlay-backdrop" data-action="close" aria-hidden="true"></div>${html}`;document.body.style.overflow='hidden';setTimeout(()=>$('#overlay button, #overlay input, #overlay a')?.focus(),0)}
function modal(title,body){drawerOpen=false;overlay(`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Cerrar">${icon('close')}</button></div>${body}</section>`)}
function drawCart(first=true){const t=calc();const html=`<section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><div class="drawer-head"><h2 id="drawer-title">Tu pedido (${t.count})</h2><button class="icon-btn" data-action="close" aria-label="Cerrar pedido">${icon('close')}</button></div><div class="drawer-body">${t.count?cartLines():empty('Tu selección está vacía.','Agregá cajas o bultos desde el catálogo.')}</div>${t.count?`<div class="drawer-bottom"><div class="summary-row total"><span>Productos</span><strong>${money(t.subtotal)}</strong></div><p class="fine">${t.pricesPending?'Precios pendientes de carga. ':''}Entrega a coordinar por WhatsApp. Pago anticipado.</p><button class="btn full secondary" data-action="stock-inquiry">Consultar stock antes de confirmar</button><a class="btn full" href="#/carrito" data-action="close-link">Revisar pedido</a></div>`:''}</section>`;if(first)overlay(html);else $('#overlay').innerHTML=`<div class="overlay-backdrop" data-action="close" aria-hidden="true"></div>${html}`;drawerOpen=true}
function openInquiry(id,type='stock'){let lines,orderNumber='';if(type==='delivery'){const o=state.orders.find(o=>o.id===id);if(!o)return;lines=o.lines;orderNumber=o.number}else if(id){const p=state.products.find(p=>p.id===id&&p.active);if(!p)return;const qty=Math.max(1,Math.min(9999,Math.floor(Number($('#detail-qty')?.value)||1)));lines=[{...p,qty}]}else lines=calc().lines;if(!lines.length){toast('Agregá productos para preparar la consulta de stock.');return}const msg=inquiryMessage(lines,{type,orderNumber});showWhatsapp(type==='delivery'?'Coordinar entrega':'Consultar stock antes de confirmar',msg)}
function showWhatsapp(title,msg){const url=whatsappURL(state.settings.whatsapp,msg);modal(title,`<p class="fine">${url?'Revisá el texto y abrí WhatsApp para enviarlo vos.':'El número comercial todavía no está configurado. Podés copiar el texto; no se enviará a un número inventado.'}</p><label class="field"><span>Mensaje preparado</span><textarea id="inquiry-message" readonly rows="8">${esc(msg)}</textarea></label><div class="row">${url?`<a class="btn" href="${esc(url)}" target="_blank" rel="noopener noreferrer" data-action="whatsapp-open">${icon('phone')}Abrir WhatsApp</a>`:'<button class="btn" disabled>WhatsApp pendiente de configurar</button>'}<button class="btn secondary" data-action="copy-inquiry">Copiar consulta</button></div><p class="fine">Abrir WhatsApp no confirma stock, pago ni entrega. La disponibilidad y las condiciones requieren respuesta del negocio.</p>`)}
function productEditor(id){const p=id==='new'?{id:'new',name:'',brand:'Marca por confirmar',flavor:'Por confirmar',size:'Caja · contenido por confirmar',saleUnit:'caja',category:'cajas',price:0,stock:null,active:true,image:'/assets/caja-pendiente.svg',description:'Producto envasado. Contenido y fotografía por confirmar.'}:state.products.find(p=>p.id===id);if(!p)return;modal(id==='new'?'Nuevo producto':'Editar producto',`<form data-form="product-editor" data-id="${p.id}">${p.sourceFile?`<p class="fine">Referencia ${esc(p.id)} · archivo original ${esc(p.sourceFile)}. El nombre se puede editar sin cambiar la foto ni los pedidos históricos.</p>`:''}<div class="form-grid">${field('Nombre intuitivo','name',p.name,'text',true)}${field('Marca','brand',p.brand,'text',true)}${field('Sabor','flavor',p.flavor,'text',true)}${field('Contenido / presentación','size',p.size,'text',true)}<label class="field"><span>Unidad de venta</span><select name="saleUnit"><option value="caja" ${p.saleUnit==='caja'?'selected':''}>Caja completa</option><option value="bulto" ${p.saleUnit==='bulto'?'selected':''}>Bulto completo</option></select></label>${field('Único precio mayorista (ARS, admite $0)','price',p.price,'number',true)}<label class="field"><span>Stock por caja o bulto (vacío = consultar)</span><input type="number" name="stock" min="0" step="1" value="${p.stock===null?'':p.stock}"></label><label class="field"><span>Foto del producto (opcional)</span><input type="file" name="photo" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG o WebP hasta 1 MB.</small></label><label class="field span2"><span>Descripción</span><textarea name="description" required maxlength="1000">${esc(p.description)}</textarea></label></div><label class="check"><input type="checkbox" name="active" ${p.active?'checked':''}>Visible en el catálogo</label><button class="btn full">Guardar producto</button></form>`)}
function download(name,text,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function exportCSV(name,headers,rows){download(name,'\uFEFF'+[headers,...rows].map(row=>row.map(csvEscape).join(',')).join('\r\n'));toast('Archivo DEMO exportado.')}
function int(v,min=0,max=10000000){const n=Number(v);if(String(v??'').trim()===''||!Number.isSafeInteger(n)||n<min||n>max)throw Error('Ingresá un entero entre '+min+' y '+max+'.');return n}
function optionalStock(v){return String(v??'').trim()===''?null:int(v)}
function requireDemoEmail(email){if(!/@(example\.(com|org|net)|[^@]+\.(invalid|example))$/i.test(email))throw Error('Usá un correo de ejemplo, como cliente@example.invalid.');}
async function imageData(file){if(file.size>1024*1024)throw Error('La fotografía supera 1 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Usá JPG, PNG o WebP.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('No se pudo leer la foto.'));r.readAsDataURL(file)})}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='close-link'){closeOverlay();return}if(b.tagName==='BUTTON')e.preventDefault();if(a==='cart')drawCart();else if(a==='close')closeOverlay();else if(a==='add')add(id);else if(a==='favorite'){state.favorites=state.favorites.includes(id)?state.favorites.filter(v=>v!==id):[...state.favorites,id];sync();toast('Favoritos actualizados.')}else if(a==='qty'){const l=state.cart.find(l=>l.id===id),p=state.products.find(p=>p.id===id);if(!l||!p)return;const qty=l.qty+Number(b.dataset.delta);if(p.stock!==null&&qty>p.stock){toast('La cantidad supera el stock informado.');return}if(qty<=0)state.cart=state.cart.filter(l=>l.id!==id);else l.qty=Math.min(qty,9999);sync()}else if(a==='clear-old-cart'){state.cart=state.cart.filter(l=>state.products.some(p=>p.id===l.id&&p.active));sync();toast('Referencias anteriores quitadas de la selección.')}else if(a==='remove'){state.cart=state.cart.filter(l=>l.id!==id);sync()}else if(a==='load'){const y=window.scrollY;pageLimit+=9;render();window.scrollTo(0,y)}else if(a==='detail-minus'||a==='detail-plus'){const i=$('#detail-qty');if(i)i.value=Math.max(1,Math.min(Number(i.max),Number(i.value)+(a==='detail-plus'?1:-1)))}else if(a==='stock-inquiry')openInquiry(id);else if(a==='delivery-inquiry')openInquiry(id,'delivery');else if(a==='whatsapp-contact')showWhatsapp('Consultar con La Montevideana','Hola, La Montevideana. Quiero consultar sobre productos envasados por caja o bulto para mi heladería y conocer las condiciones de pago anticipado y entrega.');else if(a==='copy-inquiry'){const text=$('#inquiry-message').value;try{if(!navigator.clipboard?.writeText)throw Error();await navigator.clipboard.writeText(text);toast('Consulta copiada. No se envió ningún mensaje.')}catch{$('#inquiry-message').focus();$('#inquiry-message').select();toast('Seleccionamos el texto. Usá Copiar para llevarlo a WhatsApp.')}}else if(a==='whatsapp-open'){audit('Se abrió una consulta de WhatsApp; envío y respuesta no verificados');save()}else if(a==='edit-product')productEditor(id);else if(a==='stock-adjust'){const p=state.products.find(p=>p.id===id);modal('Ajustar stock por '+saleLabel(p),`<form data-form="stock" data-id="${p.id}"><p>${esc(p.name)}</p><label class="field"><span>Stock (vacío = a consultar)</span><input type="number" name="stock" min="0" step="1" value="${p.stock===null?'':p.stock}"></label>${field('Motivo','reason','','text',true)}<button class="btn full">Guardar ajuste DEMO</button></form>`)}else if(a==='reorder'){const o=state.orders.find(o=>o.id===id);let changed=false;for(const l of o.lines){const p=state.products.find(p=>p.id===l.id&&p.active);if(!p||p.stock===0){changed=true;continue}const old=state.cart.find(c=>c.id===l.id),qty=Math.min((old?.qty||0)+l.qty,p.stock===null?9999:p.stock);if(qty<l.qty)changed=true;if(old)old.qty=qty;else state.cart.push({id:l.id,qty})}sync();drawCart();toast(changed?'Selección agregada con cambios de disponibilidad.':'Selección agregada con el precio actual. Confirmá stock antes de comprar.')}else if(a==='logout'){state.profile=null;sync()}else if(a==='export-backup')download('montevideana-demo.json',JSON.stringify(state,null,2),'application/json');else if(a==='reset')modal('¿Restablecer esta DEMO?',`<p>Se borran las solicitudes y modificaciones locales de La Montevideana. Los datos de la primera demostración se conservan por separado.</p><button class="btn red full" data-action="confirm-reset">Restablecer datos locales</button>`);else if(a==='confirm-reset'){try{localStorage.removeItem(STORE)}catch{}closeOverlay();location.reload()}else if(a==='export-inventory')exportCSV('montevideana-inventario-demo.csv',['id','stock','nombre','presentacion','precio_mayorista'],state.products.map(p=>[p.id,p.stock??'',p.name,p.saleUnit,p.price]));else if(a==='export-orders')exportCSV('montevideana-pedidos-demo.csv',['pedido','fecha','comercio_demo','estado','pago','subtotal_productos','entrega'],state.orders.map(o=>[o.number,o.created,o.customer.business,o.status,o.payment,o.subtotal,'Costo, día y horario a coordinar por WhatsApp']));else if(a==='export-audit')exportCSV('montevideana-actividad-demo.csv',['fecha','perfil_demo','accion'],state.audit.map(a=>[a.at,a.actor,a.action]));else if(a==='demo-info')modal('Estado de la versión',`<p>La Montevideana vende por caja o bulto y con un único precio mayorista.</p><p class="fine">Precios $0 pendientes de carga. Pago anticipado requerido, sin proveedor activo. Entrega a coordinar por WhatsApp. Los datos se guardan en este navegador.</p><p class="fine">Se incorporaron el logo, su paleta y las 50 imágenes del ZIP recibido. Los nombres son orientativos; cantidades, precios y stock deben confirmarse.</p>`)});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const type=form.dataset.form,d=Object.fromEntries(new FormData(form));try{
 if(type==='search'){pageLimit=9;goto('/tienda'+(d.q.trim()?'?q='+encodeURIComponent(d.q.trim()):''))}
 else if(type==='filters'){const p=new URLSearchParams();if(d.q.trim())p.set('q',d.q.trim());if(d.presentation||d.cat!=='todos')p.set('cat',d.presentation||d.cat);if(d.available)p.set('available','1');if(d.family)p.set('family',d.family);goto('/tienda?'+p)}
 else if(type==='add-product')add(form.dataset.id,int(d.qty,1,9999));
 else if(type==='profile'){requireDemoEmail(d.email);state.profile={name:d.name.trim(),business:d.business.trim(),email:d.email.trim().toLowerCase()};audit('Perfil de comercio DEMO guardado');sync();toast('Perfil de prueba guardado.')}
 else if(type==='checkout'){requireDemoEmail(d.email);const t=calc();if(!t.lines.length)throw Error('El pedido está vacío.');if(t.stockIssues.length||t.missingProducts)throw Error('Cambió la disponibilidad. Revisá las cantidades del pedido.');if(!d.consent)throw Error('Confirmá el alcance de la demostración.');const o={id:crypto.randomUUID(),number:'LM-DEMO-'+String(state.orders.length+1).padStart(4,'0'),created:new Date().toISOString(),customer:d,...t,status:t.pricesPending?'Pendiente de precio DEMO':'Pendiente de pago DEMO',payment:'Pendiente',delivery:{mode:'whatsapp',cost:null,date:null,time:null},stockConfirmed:false};state.orders.unshift(o);state.cart=[];audit('Solicitud '+o.number+' guardada: sin pago, stock ni entrega confirmados');save();goto('/pedido/'+o.id)}
 else if(type==='product-editor'){const existing=state.products.find(p=>p.id===form.dataset.id),photo=new FormData(form).get('photo'),saleUnit=d.saleUnit==='bulto'?'bulto':'caja',image=photo?.size?await imageData(photo):existing?.image||'/assets/'+saleUnit+'-pendiente.svg';const p={...existing,id:existing?.id||'lm-'+crypto.randomUUID().slice(0,8),name:d.name.trim(),brand:d.brand.trim(),flavor:d.flavor.trim(),size:d.size.trim(),saleUnit,category:saleUnit==='caja'?'cajas':'bultos',price:int(d.price),stock:optionalStock(d.stock),active:!!d.active,image,description:d.description.trim(),provisional:photo?.size?false:existing?.provisional!==false};if(existing)state.products=state.products.map(x=>x.id===p.id?p:x);else state.products.push(p);audit('Producto '+(existing?'editado: ':'creado: ')+p.name+' · precio único mayorista');save();closeOverlay();render();toast('Producto guardado.')}
 else if(type==='stock'){const p=state.products.find(p=>p.id===form.dataset.id),qty=optionalStock(d.stock);audit('Stock '+p.name+': '+(p.stock??'a consultar')+' → '+(qty??'a consultar')+'. Motivo: '+d.reason);p.stock=qty;save();closeOverlay();render();toast('Stock DEMO actualizado.')}
 else if(type==='settings'){const phone=d.whatsapp.trim();if(phone&&!whatsappURL(phone,'consulta'))throw Error('Ingresá un número internacional válido o dejá WhatsApp vacío.');state.settings.whatsapp=phone;state.settings.contact={...state.settings.contact,address:d.address.trim(),hours:d.hours.trim()};audit('Contacto de WhatsApp y datos comerciales actualizados');sync();toast('Configuración guardada.')}
 }catch(err){if(type==='checkout')$('#checkout-error').textContent=err.message;toast(err.message||'Revisá los datos ingresados.')}});
document.addEventListener('change',async e=>{const el=e.target,type=el.dataset.change;if(type==='sort'){const r=route();r.params.set('sort',el.value);goto(r.path+'?'+r.params)}else if(type==='order-status'){const o=state.orders.find(o=>o.id===el.dataset.id),next=el.value;if(o.status==='Cancelado DEMO'){el.value=o.status;toast('La solicitud cancelada queda cerrada.');return}if(['En preparación DEMO','En reparto DEMO','Entregado DEMO'].includes(next)&&!canDispatch(o)){el.value=o.status;toast('No se puede preparar ni despachar: falta un precio válido y el pago acreditado.');return}if(next==='Pendiente de pago DEMO'&&o.pricesPending){el.value=o.status;toast('Primero deben confirmarse los precios de este pedido.');return}o.status=next;audit('Solicitud '+o.number+': '+next);sync()}else if(type==='import-inventory'){const file=el.files[0];if(!file)return;try{if(file.size>1024*1024)throw Error('CSV máximo 1 MB.');const rows=parseCSV(await file.text());if(rows.length<2)throw Error('El CSV necesita encabezados y productos.');const heads=rows.shift().map(s=>s.trim().toLowerCase()),idCol=heads.indexOf('id'),stockCol=heads.indexOf('stock');if(idCol<0||stockCol<0)throw Error('Columnas requeridas: id y stock.');const seen=new Set(),updates=rows.map((r,i)=>{if(r.length<=Math.max(idCol,stockCol))throw Error('Fila incompleta: '+(i+2));const id=r[idCol].trim(),stock=optionalStock(r[stockCol]);if(!state.products.some(p=>p.id===id))throw Error('Producto desconocido: '+id);if(seen.has(id))throw Error('ID repetido: '+id);seen.add(id);return{id,stock}});modal('Revisar importación',`<p class="fine">${updates.length} productos validados. Vacío significa stock a consultar.</p><div class="table-wrap"><table><thead><tr><th>PRODUCTO</th><th>NUEVO STOCK</th></tr></thead><tbody>${updates.map(u=>`<tr><td>${esc(state.products.find(p=>p.id===u.id).name)}</td><td>${u.stock??'A consultar'}</td></tr>`).join('')}</tbody></table></div><button class="btn full mt" id="confirm-import">Aplicar importación DEMO</button>`);$('#confirm-import').onclick=()=>{updates.forEach(u=>{state.products.find(p=>p.id===u.id).stock=u.stock});audit('Importación de inventario DEMO: '+updates.length+' productos');save();closeOverlay();render();toast('Inventario actualizado.')};}catch(err){toast(err.message)}el.value=''}});
document.addEventListener('keydown',e=>{if(!$('#overlay').innerHTML)return;if(e.key==='Escape'){closeOverlay();return}if(e.key==='Tab'){const list=[...$('#overlay').querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select,textarea')].filter(x=>x.offsetParent!==null),first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',()=>{closeOverlay();pageLimit=9;render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true})});
window.addEventListener('storage',e=>{if(e.key===STORE){const next=read();if(next){state=next;render();if(drawerOpen)drawCart(false)}}});
document.documentElement.style.setProperty('--blue',state.settings.colors.primary);
document.documentElement.style.setProperty('--red',state.settings.colors.accent);
document.documentElement.style.setProperty('--sky',state.settings.colors.surface);
document.documentElement.style.setProperty('--navy',state.settings.colors.navy);
if(saved&&saved.catalogRevision!==config.catalogVersion)save();
render();
